<?php require 'config.php';require_login();$title='Salary records';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('INSERT INTO salaries(employee_id,month,amount,paid_on,status) VALUES(?,?,?,?,?)')->execute([(int)$_POST['employee_id'],$_POST['month'],(float)$_POST['amount'],$_POST['paid_on']?:null,$_POST['status']]);flash('Salary record saved.');go('salaries.php');}
$emps=$pdo->query('SELECT id,name FROM employees ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT s.*,e.name FROM salaries s JOIN employees e ON e.id=s.employee_id ORDER BY s.id DESC')->fetchAll();require 'partials/header.php';?>
<div class="pagehead"><div><div class="eyebrow">PAYROLL</div><h1>Salary records</h1><p class="sub">Maintain monthly salary and payment records.</p></div></div>
<div class="card"><h2>Add salary record</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid" style="margin-top:15px"><div class="field"><label>Employee</label><select name="employee_id" required><?php foreach($emps as $e):?><option value="<?=$e['id']?>"><?=h($e['name'])?></option><?php endforeach?></select></div><div class="field"><label>Month</label><input type="month" name="month" value="<?=date('Y-m')?>" required></div><div class="field"><label>Amount (₹)</label><input type="number" step="0.01" min="0" name="amount" required></div><div class="field"><label>Payment date</label><input type="date" name="paid_on"></div><div class="field"><label>Status</label><select name="status"><option>Paid</option><option>Pending</option></select></div></div><div class="actions"><button class="btn">Save salary record</button></div></form></div>
<div class="card"><div class="cardhead"><h2>Payroll history</h2></div><div class="tablewrap"><table><thead><tr><th>Employee</th><th>Month</th><th>Amount</th><th>Paid on</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['month'])?></td><td>₹<?=number_format((float)$r['amount'],2)?></td><td><?=h($r['paid_on'])?></td><td><span class="badge <?=$r['status']==='Pending'?'warn':''?>"><?=h($r['status'])?></span></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="5" class="empty">No salary records yet.</td></tr><?php endif?></tbody></table></div></div><?php require 'partials/footer.php';?>
